⟦vr:model⟧ = MLPRegressor(hidden_layer_sizes=(48, 48), solver="adam",
                          learning_rate_init=0.02, random_state=0)
⟦vr:best⟧ = (0, float("inf"))
⟦vr:patience⟧, ⟦vr:bad_epochs⟧ = 30, 0
